PREFIX llo: <http://trustgraph.ai/ontologies/lithuanian-legal#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?label ?docID ?dateEnacted
WHERE {
  ?doc a llo:Statute ;
       rdfs:label ?label ;
       llo:hasDocID ?docID .
  OPTIONAL { ?doc llo:dateEnacted ?dateEnacted . }
  FILTER(LANG(?label) = "en" || LANG(?label) = "")
}
ORDER BY ?dateEnacted

PREFIX llo: <http://trustgraph.ai/ontologies/lithuanian-legal#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?label ?docID ?dateEnacted
WHERE {
  ?doc a llo:LegislativeDraft ;
       rdfs:label ?label ;
       llo:hasDocID ?docID .
  OPTIONAL { ?doc llo:dateEnacted ?dateEnacted . }
  FILTER(LANG(?label) = "en" || LANG(?label) = "")
}
ORDER BY ?dateEnacted

PREFIX llo: <http://trustgraph.ai/ontologies/lithuanian-legal#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?docLabel ?componentLabel ?indexNumber
WHERE {
  ?doc a llo:LegalDocument ;
       rdfs:label ?docLabel ;
       llo:hasComponent ?component .
  ?component rdfs:label ?componentLabel ;
             llo:hasIndexNumber ?indexNumber .
  FILTER(LANG(?docLabel) = "en" || LANG(?docLabel) = "")
  FILTER(LANG(?componentLabel) = "en" || LANG(?componentLabel) = "")
}
ORDER BY ?docLabel ?indexNumber

PREFIX llo: <http://trustgraph.ai/ontologies/lithuanian-legal#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?amendingLabel ?amendingID ?targetLabel ?targetID
WHERE {
  ?amending llo:proposesAmendmentTo ?target ;
            rdfs:label ?amendingLabel ;
            llo:hasDocID ?amendingID .
  ?target rdfs:label ?targetLabel ;
          llo:hasDocID ?targetID .
  FILTER(LANG(?amendingLabel) = "en" || LANG(?amendingLabel) = "")
  FILTER(LANG(?targetLabel) = "en" || LANG(?targetLabel) = "")
}
ORDER BY ?amendingID

PREFIX llo: <http://trustgraph.ai/ontologies/lithuanian-legal#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?docLabel ?docID ?directiveLabel
WHERE {
  ?doc llo:transposesDirective ?directive ;
       rdfs:label ?docLabel ;
       llo:hasDocID ?docID .
  ?directive rdfs:label ?directiveLabel .
  FILTER(LANG(?docLabel) = "en" || LANG(?docLabel) = "")
  FILTER(LANG(?directiveLabel) = "en" || LANG(?directiveLabel) = "")
}
ORDER BY ?docLabel

PREFIX llo: <http://trustgraph.ai/ontologies/lithuanian-legal#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?authorityLabel ?domain ?comment
WHERE {
  ?auth a llo:JurisdictionAuthority ;
        rdfs:label ?authorityLabel .
  OPTIONAL { ?auth llo:hasGovernanceDomain ?domain . }
  OPTIONAL { ?auth rdfs:comment ?comment . FILTER(LANG(?comment) = "en" || LANG(?comment) = "") }
  FILTER(LANG(?authorityLabel) = "en" || LANG(?authorityLabel) = "")
}
ORDER BY ?authorityLabel

PREFIX llo: <http://trustgraph.ai/ontologies/lithuanian-legal#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?entityLabel ?type ?isPublicAdmin
WHERE {
  ?entity a ?type ;
          rdfs:label ?entityLabel .
  ?type rdfs:subClassOf* llo:RegulatedEntity .
  OPTIONAL { ?entity llo:isPublicAdministration ?isPublicAdmin . }
  FILTER(LANG(?entityLabel) = "en" || LANG(?entityLabel) = "")
  FILTER(?type != llo:RegulatedEntity)
}
ORDER BY ?type ?entityLabel

PREFIX llo: <http://trustgraph.ai/ontologies/lithuanian-legal#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?riskLabel ?type ?comment
WHERE {
  ?risk a ?type ;
        rdfs:label ?riskLabel .
  ?type rdfs:subClassOf* llo:RiskThreat .
  OPTIONAL { ?risk rdfs:comment ?comment . FILTER(LANG(?comment) = "en" || LANG(?comment) = "") }
  FILTER(LANG(?riskLabel) = "en" || LANG(?riskLabel) = "")
  FILTER(?type != llo:RiskThreat)
}
ORDER BY ?type ?riskLabel

PREFIX llo: <http://trustgraph.ai/ontologies/lithuanian-legal#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?actorLabel ?vectorLabel
WHERE {
  ?actor a llo:HostileActor ;
         rdfs:label ?actorLabel ;
         llo:utilizesVector ?vector .
  ?vector rdfs:label ?vectorLabel .
  FILTER(LANG(?actorLabel) = "en" || LANG(?actorLabel) = "")
  FILTER(LANG(?vectorLabel) = "en" || LANG(?vectorLabel) = "")
}
ORDER BY ?actorLabel ?vectorLabel

PREFIX llo: <http://trustgraph.ai/ontologies/lithuanian-legal#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?mandateLabel ?type ?legalBasis ?comment
WHERE {
  ?mandate a ?type ;
           rdfs:label ?mandateLabel .
  ?type rdfs:subClassOf* llo:ResilienceMandate .
  OPTIONAL { ?mandate llo:hasLegalBasis ?legalBasis . }
  OPTIONAL { ?mandate rdfs:comment ?comment . FILTER(LANG(?comment) = "en" || LANG(?comment) = "") }
  FILTER(LANG(?mandateLabel) = "en" || LANG(?mandateLabel) = "")
}
ORDER BY ?type ?mandateLabel

PREFIX llo: <http://trustgraph.ai/ontologies/lithuanian-legal#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?penaltyLabel ?maxTurnover ?legalBasis
WHERE {
  ?penalty a llo:FinancialPenalty ;
           rdfs:label ?penaltyLabel .
  OPTIONAL { ?penalty llo:hasMaxTurnoverPercentage ?maxTurnover . }
  OPTIONAL { ?penalty llo:hasLegalBasis ?legalBasis . }
  FILTER(LANG(?penaltyLabel) = "en" || LANG(?penaltyLabel) = "")
}
ORDER BY DESC(?maxTurnover)

PREFIX llo: <http://trustgraph.ai/ontologies/lithuanian-legal#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?mechanismLabel ?type ?isPersonal ?comment
WHERE {
  ?mechanism a ?type ;
             rdfs:label ?mechanismLabel .
  ?type rdfs:subClassOf* llo:LiabilityEnforcement .
  OPTIONAL { ?mechanism llo:isPersonalHazard ?isPersonal . }
  OPTIONAL { ?mechanism rdfs:comment ?comment . FILTER(LANG(?comment) = "en" || LANG(?comment) = "") }
  FILTER(LANG(?mechanismLabel) = "en" || LANG(?mechanismLabel) = "")
  FILTER(?type != llo:LiabilityEnforcement)
}
ORDER BY ?type ?mechanismLabel

PREFIX llo: <http://trustgraph.ai/ontologies/lithuanian-legal#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?rightLabel ?statuteLabel ?comment
WHERE {
  ?statute llo:guaranteesRightTo ?right ;
           rdfs:label ?statuteLabel .
  ?right rdfs:label ?rightLabel .
  OPTIONAL { ?right rdfs:comment ?comment . FILTER(LANG(?comment) = "en" || LANG(?comment) = "") }
  FILTER(LANG(?rightLabel) = "en" || LANG(?rightLabel) = "")
  FILTER(LANG(?statuteLabel) = "en" || LANG(?statuteLabel) = "")
}
ORDER BY ?rightLabel

PREFIX llo: <http://trustgraph.ai/ontologies/lithuanian-legal#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?triggerLabel ?responseWindow ?emergencyLimit ?isExtraordinary
WHERE {
  ?trigger a llo:IncidentTrigger ;
           rdfs:label ?triggerLabel .
  OPTIONAL { ?trigger llo:hasResponseWindow ?responseWindow . }
  OPTIONAL { ?trigger llo:hasEmergencyLimit ?emergencyLimit . }
  OPTIONAL { ?trigger llo:isExtraordinaryPower ?isExtraordinary . }
  FILTER(LANG(?triggerLabel) = "en" || LANG(?triggerLabel) = "")
}
ORDER BY ?triggerLabel

PREFIX llo: <http://trustgraph.ai/ontologies/lithuanian-legal#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?restrictionLabel ?prohibitedOrigin ?legalBasis
WHERE {
  ?restriction a llo:SupplyChainRestriction ;
               rdfs:label ?restrictionLabel .
  OPTIONAL { ?restriction llo:prohibitsGeopoliticalOrigin ?prohibitedOrigin . }
  OPTIONAL { ?restriction llo:hasLegalBasis ?legalBasis . }
  FILTER(LANG(?restrictionLabel) = "en" || LANG(?restrictionLabel) = "")
}
ORDER BY ?restrictionLabel
